<?php
require_once dirname(__DIR__,3)."/includes/borrower_check.php";require_once dirname(__DIR__,3)."/config/db.php";require_once dirname(__DIR__,3)."/includes/request_helper.php";require_once dirname(__DIR__,3)."/includes/adviser_endorsement_helper.php";
$facultyId=(int)$_SESSION["user_id"];if(!gsoIsApprovedFaculty($pdo,$facultyId))redirectWithFlash("browse.php","Faculty Endorsement access is not available for this account.");
$s=$pdo->prepare("SELECT rr.request_id,rr.request_date,rr.adviser_state,rr.date_needed,rr.notes,b.full_name AS student_name,r.resource_name FROM resource_requests rr JOIN users b ON b.user_id=rr.borrower_id JOIN ".gsoRequestResourceRollupSql()." r ON r.request_id=rr.request_id WHERE rr.adviser_user_id=:uid AND rr.status<>'Cancelled' ORDER BY (rr.adviser_state='Pending Adviser') DESC,rr.request_date DESC");$s->execute([":uid"=>$facultyId]);$rows=$s->fetchAll(PDO::FETCH_ASSOC)?:[];
$pageTitle="Endorsements";$activePage="endorsements";require dirname(__DIR__,3)."/includes/header.php";require dirname(__DIR__,3)."/includes/borrower_sidebar.php";?>
<div class="main-content"><?php require dirname(__DIR__,3)."/includes/borrower_topbar.php";?><main class="page-content"><section class="card"><h2>Endorsements</h2><p>Requests assigned to you as Adviser / Subject Teacher.</p></section><section class="card"><div class="table-wrapper"><table class="request-table"><thead><tr><th>Reference</th><th>Student</th><th>Resource</th><th>Date</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6">No assigned endorsements.</td></tr><?php else:foreach($rows as $r):?><tr><td>REQ-<?php echo str_pad((string)$r['request_id'],3,'0',STR_PAD_LEFT);?></td><td><?php echo htmlspecialchars($r['student_name']);?></td><td><?php echo htmlspecialchars($r['resource_name']);?></td><td><?php echo htmlspecialchars((string)$r['date_needed']);?></td><td><?php echo htmlspecialchars($r['adviser_state']);?></td><td><a href="endorsement_detail.php?request_id=<?php echo (int)$r['request_id'];?>">View</a></td></tr><?php endforeach;endif;?></tbody></table></div></section></main></div><?php require dirname(__DIR__,3)."/includes/footer.php";
